def transform(grid):
    height = len(grid) // 4
    width = len(grid[0])
    out = [row[:] for row in grid[:height]]
    for color_block in (1, 3, 2):
        for r in range(height):
            for c in range(width):
                value = grid[color_block * height + r][c]
                if out[r][c] == 0 and value != 0:
                    out[r][c] = value
    return out
